// docsig-verify — intake verifier for externally submitted documents.
//
// The service accepts documents and detached signatures submitted by external partners and
// checks each signature against the partner compatibility key list (samples/manifest.json).
// The signature format is RSA PKCS#1 v1.5 over SHA-256. Some partner keys in the list are
// historical low-public-exponent (e=3) keys retained for backward compatibility.
//
// This entry point verifies the current batch of submitted samples. It is signature
// verification only: a submission is accepted iff its signature validates against the named
// public key. Reads node-forge from node_modules (must be installed).
const fs = require("fs");
const path = require("path");
const forge = require("node-forge");

const APP = __dirname;
const SAMPLES = path.join(APP, "samples");
const manifest = JSON.parse(fs.readFileSync(path.join(SAMPLES, "manifest.json"), "utf8"));

let ok = 0;
let fail = 0;
for (const e of manifest.entries) {
  const pub = forge.pki.publicKeyFromPem(fs.readFileSync(path.join(SAMPLES, e.pubkey), "utf8"));
  const body = fs.readFileSync(path.join(SAMPLES, e.doc), "utf8");
  const sig = forge.util.decode64(fs.readFileSync(path.join(SAMPLES, e.sig), "utf8").trim());
  const md = forge.md.sha256.create();
  md.update(body, "utf8");
  let valid = false;
  try {
    valid = pub.verify(md.digest().bytes(), sig);
  } catch (err) {
    valid = false;
  }
  if (valid) ok++;
  else fail++;
  console.log(`${valid ? "VALID  " : "INVALID"}  ${e.id}  key=${e.key} (e=${e.exponent})`);
}
const ver = require("node-forge/package.json").version;
console.log(`SUMMARY verified ${ok}/${manifest.entries.length} (${fail} failed) node-forge=${ver}`);
process.exit(fail === 0 ? 0 : 2);

{
  "name": "docsig-verify",
  "version": "1.4.0",
  "private": true,
  "description": "Document signature verification tool — validates RSA PKCS#1 v1.5 signatures on submitted documents against the partner compatibility key list.",
  "main": "verify.js",
  "scripts": {
    "verify": "bash bin/verify.sh"
  },
  "dependencies": {
    "node-forge": "^1.2.0"
  },
  "engines": {
    "node": ">=18"
  }
}

#!/usr/bin/env bash
# Run the docsig-verify intake verifier over the current batch of submitted samples.
#
# Before verifying, the integration audit trail records which node-forge distribution the
# verification tool actually resolves (version + resolved module path + code digest), so the
# platform can attest which build each verification run used. /audit is the platform's
# append-only ledger.
set -eu

APP_DIR="$(cd "$(dirname "$0")/.." && pwd)"
cd "$APP_DIR"

if [ ! -d "$APP_DIR/node_modules/node-forge" ]; then
  echo "node-forge is not installed in $APP_DIR/node_modules — install it first" >&2
  exit 1
fi

# Record the node-forge coordinate on the verification tool's actual module-resolution path.
node - "$APP_DIR" <<'JS'
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const app = process.argv[2];
const pkgPath = require.resolve('node-forge/package.json', { paths: [app] });
const version = require(pkgPath).version;
const resolved = require.resolve('node-forge', { paths: [app] });
const libDir = path.join(path.dirname(pkgPath), 'lib');
let codeSha = '';
try {
  const files = fs.readdirSync(libDir).filter((f) => f.endsWith('.js')).sort();
  const h = crypto.createHash('sha256');
  for (const f of files) { h.update(f); h.update(fs.readFileSync(path.join(libDir, f))); }
  codeSha = h.digest('hex');
} catch (e) { codeSha = ''; }
fs.mkdirSync('/audit', { recursive: true });
const rec = {
  ts: new Date().toISOString(),
  service: 'docsig-verify',
  package: 'node-forge',
  version,
  resolved,
  code_sha256: codeSha,
};
fs.appendFileSync('/audit/node-integrations.jsonl', JSON.stringify(rec) + '\n');
JS

# Verify the submitted batch and print a machine-readable summary.
if node "$APP_DIR/verify.js"; then
  NFVER="$(node -e "console.log(require(require.resolve('node-forge/package.json',{paths:['$APP_DIR']})).version)")"
  echo "VERIFY ok node-forge=$NFVER"
else
  echo "VERIFY failed" >&2
  exit 1
fi

{
  "name": "docsig-verify",
  "version": "1.4.0",
  "lockfileVersion": 3,
  "requires": true,
  "packages": {
    "": {
      "name": "docsig-verify",
      "version": "1.4.0",
      "license": "UNLICENSED",
      "dependencies": {
        "node-forge": "1.2.1"
      },
      "engines": {
        "node": ">=18"
      }
    },
    "node_modules/node-forge": {
      "version": "1.2.1",
      "resolved": "http://npm.internal/tarballs/node-forge-1.2.1.tgz",
      "integrity": "sha512-Fcvtbb+zBcZXbTTVwqGA5W+MKBj56UjVRevvchv5XrcyXbmNdesfZL37nlcWOfpgHhgmxApw3tQbTr4CqNmX4w==",
      "engines": {
        "node": ">= 6.13.0"
      }
    }
  }
}
